/* Guided walkthrough for the fictional family demo. */
(()=>{
'use strict';
let current=0,buddyName='Miso',panel=null,spotlight=null,activeTarget=null,previousFocus=null;
const featureNames=['Your buddy’s world','Choose activity','Learning lessons','Meal studio','Your pace. Your plan.','Wardrobe & shop','Mini games','Meal reminders','Your coins','Parent portal','Your buddy’s world'];
const steps=[
 {page:'home',target:'.scene',title:n=>`Hi, I’m ${n}! Welcome to DiaBuddy!`,text:'This is our little world. We can hang out here and choose an activity together.'},
 {page:'home',target:'#activity',title:()=> 'Choose an activity',text:'Tap here to see what your buddy can do, like reading, dancing, or sleeping.'},
 {page:'home',target:'.bunny-intro',title:()=> 'Learn a little with me',text:'Open our little lessons to explore type 1 diabetes and practice talking about it together.'},
 {page:'home',target:'.meal-card',title:()=> 'Share a pretend meal',text:'Try one of the example meals and see its pixel-art illustration. In this demo, use fictional examples.'},
 {page:'home',target:'#timer-panel',title:()=> 'Your pace. Your plan.',text:'This timer is optional and never starts automatically. A grown-up can set a time in the parent portal or let you choose a time within their approved range. You can stop the timer anytime.'},
 {page:'wardrobe',target:'[data-page="wardrobe"]',title:()=> 'Dress up your buddy',text:'Explore outfits, accessories, and different looks in the wardrobe and shop.'},
 {page:'games',target:'[data-page="games"]',title:()=> 'Play mini games',text:'Visit the playroom for puzzles and little adventures at your own pace.'},
 {page:'reminders',target:'[data-page="reminders"]',title:()=> 'Gentle reminders',text:'When you’re at a restaurant, a gentle reminder can invite you to take a look at DiaBuddy. Restaurant visits are simulated in this demo.'},
 {page:'home',target:'.bank',title:()=> 'Collect coins',text:'Coins are for little in-app rewards. Explore, learn, and play at your own pace.'},
 {page:'home',target:'#portal-select',title:()=> 'A space for grown-ups',text:'A grown-up can explore the parent view. The demo toggle is not a real account or secure family link.'},
 {page:'home',target:'.scene',title:()=> 'Ready to explore?',text:'That’s our little tour! We can always come back to My little world.'}
];
function clearHighlight(){document.querySelectorAll('.family-tour-highlight').forEach(el=>el.classList.remove('family-tour-highlight'));activeTarget=null}
function positionSpotlight(){if(!spotlight||!activeTarget?.isConnected)return;const rect=activeTarget.getBoundingClientRect(),padding=8,left=Math.max(4,rect.left-padding),top=Math.max(4,rect.top-padding),right=Math.min(window.innerWidth-4,rect.right+padding),bottom=Math.min(window.innerHeight-4,rect.bottom+padding);if(right<=left||bottom<=top){spotlight.hidden=true;return}spotlight.hidden=false;Object.assign(spotlight.style,{left:left+'px',top:top+'px',width:(right-left)+'px',height:(bottom-top)+'px'});spotlight.classList.toggle('family-tour-spotlight-low',top<42)}
function finish(){clearHighlight();window.removeEventListener('scroll',positionSpotlight,true);window.removeEventListener('resize',positionSpotlight);spotlight?.remove();spotlight=null;panel?.remove();panel=null;go('home');if(previousFocus?.isConnected)previousFocus.focus()}
function show(){clearHighlight();const item=steps[current];go(item.page);const target=document.querySelector(item.target);activeTarget=target;if(target){target.classList.add('family-tour-highlight');target.scrollIntoView?.({block:'center',inline:'nearest',behavior:'instant'})}panel.innerHTML=`<div class="family-tour-top"><span>✦ &nbsp; A LITTLE TOUR · ${current+1} OF ${steps.length}</span><button class="family-tour-skip" type="button" id="tour-skip">Close tour</button></div><div class="family-tour-feature">✦ &nbsp; LOOK FOR: ${escapeHTML(featureNames[current])}</div><h2 id="family-tour-title" tabindex="-1">${escapeHTML(item.title(window.DiaNames?.current()||buddyName))}</h2><p>${escapeHTML(item.text)}</p><div class="family-tour-actions">${current?'<button class="secondary" type="button" id="tour-back">← Back</button>':''}<button class="primary" type="button" id="tour-next">${current===steps.length-1?'Let’s explore!':'Next →'}</button></div>`;panel.querySelector('#tour-skip').onclick=finish;panel.querySelector('#tour-back')?.addEventListener('click',()=>{current--;show()});panel.querySelector('#tour-next').onclick=()=>{if(current===steps.length-1)finish();else{current++;show()}};panel.querySelector('#family-tour-title').focus({preventScroll:true});positionSpotlight();requestAnimationFrame(positionSpotlight)}
window.DiaFamilyTour={stopForCare(){if(panel)finish();},start(name){buddyName=String(name||'Miso');current=0;previousFocus=document.activeElement;panel?.remove();spotlight?.remove();spotlight=document.createElement('div');spotlight.className='family-tour-spotlight';spotlight.setAttribute('aria-hidden','true');spotlight.innerHTML='<span>✦ LOOK HERE</span>';document.body.appendChild(spotlight);window.addEventListener('scroll',positionSpotlight,true);window.addEventListener('resize',positionSpotlight);panel=document.createElement('div');panel.className='family-tour';panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','family-tour-title');document.body.appendChild(panel);show()}};
})();
